import type { AddonType } from "@/lib/addon-types"
import type { DeepQuestion } from "@/lib/deep-assessment"

/**
 * The lens questions — the few extra questions a purchased add-on adds to the
 * deep assessment.
 *
 * ── Why this is a deterministic bank ─────────────────────────────────────────
 *
 * The core deep questions are generated by Claude (app/api/generate-deep-questions),
 * which is right for them: they probe the WHY behind a particular score profile
 * and benefit from variation. The lens questions are the opposite job. The
 * report has to interpret them, so the interpreter needs to know what it is
 * reading — a fixed set of ids and answer values it can branch on. A generated
 * lens question would give the fallback builder nothing reliable to key off,
 * and "every add-on changes the question set" could then only be asserted as
 * shape rather than content, and only when an API key is present.
 *
 * ── Scope ────────────────────────────────────────────────────────────────────
 *
 * Four to five questions each. This is a lens on the foundation assessment, not
 * a second assessment: the standalone Stability, Glucose, Mind and Performance
 * assessments still exist at their own routes and go far deeper. These ask only
 * what the lens chapter needs in order to say something specific.
 *
 * ── Rules these questions obey ───────────────────────────────────────────────
 *
 *  1. Non-diagnostic and non-judgemental. They ask what someone NOTICES, never
 *     what they have. No symptom checklist that reads as a screening tool.
 *  2. No medical measurement the product cannot verify — no HbA1c, no fasting
 *     glucose, no blood pressure, no diagnoses, no medication names, no weight
 *     targets. Glucose in particular asks about observed energy and craving
 *     PATTERNS, because this questionnaire does not measure blood glucose and
 *     must not imply that it does. `tests/unit/addon-questions.test.ts` greps
 *     the banks for those terms.
 *  3. Answer options are stable `value` strings. The lens builder branches on
 *     them, so renaming a value is a breaking change to report content.
 *  4. Family wording where the personal phrasing would not fit a household.
 *
 * The `intent` / `answerField` / `whyNeeded` metadata on every spec is not
 * decoration: it is what the review pack is generated from, so the
 * documentation cannot drift away from the questions it describes.
 */

export interface AddonQuestionSpec {
  /** Stable id. `lens<n>` — never `dq<n>`, which is the core generated set. */
  id: string
  type: DeepQuestion["type"]
  /** Which pathway this question informs, for the existing DeepPillar typing. */
  pillar: DeepQuestion["pillar"]
  text: string
  /** Household phrasing. Omitted when the personal wording already fits. */
  familyText?: string
  eduContext?: string
  familyEduContext?: string
  options?: Array<{ label: string; value: string }>
  min?: number
  max?: number
  minLabel?: string
  maxLabel?: string
  required: boolean

  /* ── Documentation, carried as data ── */
  /** What this question is intended to support in the report. */
  intent: string
  /** The field of the lens chapter its answer feeds. */
  answerField: string
  /** Why the lens cannot say something useful without it. */
  whyNeeded: string
}

const FREQ5 = [
  { label: "Rarely or never", value: "rarely" },
  { label: "About once a week", value: "weekly" },
  { label: "A few times a week", value: "often" },
  { label: "Most days", value: "daily" },
  { label: "I'm not sure", value: "unsure" },
]

