export const ADDON_QUESTIONS: Record<AddonType, AddonQuestionSpec[]> = {
  stability: STABILITY,
  glucose: GLUCOSE,
  mind: MIND,
  performance: PERFORMANCE,
}

/**
 * The lens questions for a purchased add-on, in `DeepQuestion` shape.
 *
 * Returns `[]` for `null` — the no-add-on questionnaire is then byte-identical
 * to what it was before this existed, which is the property
 * `tests/unit/addon-questions.test.ts` pins.
 */
export function addonQuestionsFor(
  addon: AddonType | null | undefined,
  foundation: "you" | "family" = "you",
): DeepQuestion[] {
  if (!addon) return []
  const specs = ADDON_QUESTIONS[addon]
  if (!specs) return []

  const family = foundation === "family"

  return specs.map((spec) => ({
    id: spec.id,
    type: spec.type,
    pillar: spec.pillar,
    section: "lens" as const,
    text: family && spec.familyText ? spec.familyText : spec.text,
    eduContext: family && spec.familyEduContext ? spec.familyEduContext : spec.eduContext,
    ...(spec.options ? { options: spec.options } : {}),
    ...(spec.min !== undefined ? { min: spec.min } : {}),
    ...(spec.max !== undefined ? { max: spec.max } : {}),
    ...(spec.minLabel ? { minLabel: spec.minLabel } : {}),
    ...(spec.maxLabel ? { maxLabel: spec.maxLabel } : {}),
    required: spec.required,
  }))
}

/** The lens answers only, keyed by question id — what the lens builder reads. */
export function lensAnswers(
  addon: AddonType | null | undefined,
  answers: Record<string, unknown>,
): Record<string, unknown> {
  if (!addon) return {}
  const ids = new Set(ADDON_QUESTIONS[addon]?.map((q) => q.id) ?? [])
  return Object.fromEntries(Object.entries(answers).filter(([k]) => ids.has(k)))
}
